int menu_difficulty()
{
    int quit = 0;
    int selector = 0;
    int maxdisplay = 14; //TAG_YO cambiado el máximo de opciones que se puedes mostrar de forma simultanea en el menú de selección de modos
    int init_menu_y = -5;
    int i, j, t;
    //float slider = 0;
    int barx, bary, barw, barh;
    s_drawmethod drawmethod = plainmethod;
    drawmethod.alpha = 1;

    barx = videomodes.hRes / 5;
    bary = _liney(0, 0) - 2;
    barw = videomodes.hRes * 3 / 5;
    barh = 5 * (fontheight(0) + 1) + 4;
    newgameMenu = 1;
    bothnewkeys = 0;

    loadGameFile();

    while(!quit)
    {
        if(num_difficulties > 1)
        {
            _menutextm(2, -5, 0, Tr("Game Mode"));
            t = (selector - (selector == num_difficulties)) / maxdisplay * maxdisplay;
            for(j = 0, i = t; i < maxdisplay + t && i < num_difficulties; j++, i++)
            {
                if(j < maxdisplay)
                {
                    if(bonus >= levelsets[i].ifcomplete)
                    {
                        _menutextm((selector == i), init_menu_y + j, 0, "%s", levelsets[i].name);
                    }
                    else
                    {
                        if(levelsets[i].ifcomplete > 1)
                        {
                            _menutextm((selector == i), init_menu_y + j, 0, Tr("%s - Finish Game %i Times To UnLock"), levelsets[i].name, levelsets[i].ifcomplete);
                        }
                        else
                        {
                            _menutextm((selector == i), init_menu_y + j, 0, Tr("%s - Finish Game To UnLock"), levelsets[i].name);
                        }
                    }
                }
                else
                {
                    break;
                }
            }
            _menutextm((selector == i), init_menu_y + MIN(num_difficulties, maxdisplay) + 3, 0, Tr("Back"));

            //draw the scroll bar
            if(num_difficulties > maxdisplay)
            {
                spriteq_add_box(barx,  bary,        barw,     barh,   0, color_black, &drawmethod); //outerbox
                spriteq_add_line(barx, bary,  barx + 8, bary, 1, color_white, NULL);
                spriteq_add_line(barx, bary, barx, bary + barh, 1, color_white, NULL);
                spriteq_add_line(barx + 8, bary, barx + 8, bary + barh,  1, color_white, NULL);
                spriteq_add_line(barx, bary + barh, barx + 8, bary + barh,  1, color_white, NULL);
                spriteq_add_box(barx + 1,  bary + selector * (barh - 3) / num_difficulties, 7,             3,            2, color_white, NULL); //slider
            }
        }

        update(0, 0);

        if(num_difficulties == 1) // OX. Mods with only one set will auto load that difficulty.
        {
            if(selector == num_difficulties)
            {
                quit = 1;
            }
            else if(bonus >= levelsets[selector].ifcomplete)
            {
                saveslot = selector;
                strncpy(savelevel[saveslot].dName, levelsets[saveslot].name, MAX_NAME_LEN - 1);
                newgameMenu = 0;
                return saveslot;
            }
        }

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            --selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(selector < 0)
        {
            selector = num_difficulties;
        }
        if(selector > num_difficulties)
        {
            selector = 0;
        }
        //if(selector<num_difficulties) slider = selector * 4.5;

        if(bothnewkeys & FLAG_ANYBUTTON)
        {

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            if(selector == num_difficulties)
            {
                quit = 1;
            }
            else if(bonus >= levelsets[selector].ifcomplete)
            {
                saveslot = selector;
                strncpy(savelevel[saveslot].dName, levelsets[saveslot].name, MAX_NAME_LEN - 1);
                newgameMenu = 0;
                return saveslot;
            }
        }
    }
    bothnewkeys = 0;
    newgameMenu = 0;
    return -1;
}

functions.menu_options:
void menu_options()
{
    #define TOT_CHEATS          3
    #define OPT_Y_POS          -1
    #define OPT_X_POS          -7
    #define CHEAT_PAUSE_POSY    3

    typedef enum {
        VIDEO_OPTION,
        SOUND_OPTION,
        CONTROL_OPTION,
        SYSTEM_OPTION,

        LIVES_CHEAT,
        CREDITS_CHEAT,
        HEALTH_CHEAT,

        END_OPTION
    } e_selector;

    int quit = 0;
    int y_offset = OPT_Y_POS;
    int BACK_OPTION = END_OPTION-TOT_CHEATS;
    int cheat_opt_offset = 0;
    e_selector selector = VIDEO_OPTION;

    optionsMenu = 1;
    bothnewkeys = 0;

    if (cheats && !forcecheatsoff)
    {
        if(level != NULL && _pause > 0) y_offset += CHEAT_PAUSE_POSY;
        y_offset -= TOT_CHEATS;
        cheat_opt_offset += 1;
        BACK_OPTION += TOT_CHEATS;
    }

    while(!quit)
    {
        if (!cheats || forcecheatsoff) _menutextm(2, -5, 0, Tr("Options")); else _menutextm(2, -5, 0, Tr("Cheat Options"));

        _menutextm((selector == VIDEO_OPTION), y_offset+VIDEO_OPTION, 0, Tr("Video Options..."));
        _menutextm((selector == SOUND_OPTION), y_offset+SOUND_OPTION, 0, Tr("Sound Options..."));
        _menutextm((selector == CONTROL_OPTION), y_offset+CONTROL_OPTION, 0, Tr("Control Options..."));
        _menutextm((selector == SYSTEM_OPTION), y_offset+SYSTEM_OPTION, 0, Tr("System Options..."));

        if (cheats && !forcecheatsoff)
        {
            _menutext((selector == LIVES_CHEAT), OPT_X_POS, y_offset+cheat_opt_offset+LIVES_CHEAT, (livescheat)?Tr("Infinite Lives On"):Tr("Infinite Lives Off"));
            _menutext((selector == CREDITS_CHEAT), OPT_X_POS, y_offset+cheat_opt_offset+CREDITS_CHEAT, (creditscheat)?Tr("Infinite Credits On"):Tr("Infinite Credits Off"));    // Enemies fall/don't fall down when you respawn
            _menutext((selector == HEALTH_CHEAT), OPT_X_POS, y_offset+cheat_opt_offset+HEALTH_CHEAT, (healthcheat)?Tr("Infinite Health On"):Tr("Infinite Health Off"));    // Enemies fall/don't down when you respawn
        }

        _menutextm((selector == BACK_OPTION), y_offset+cheat_opt_offset+BACK_OPTION+2, 0, Tr("Back"));

        update((level != NULL), 0);

        if(bothnewkeys & FLAG_ESC)
        {
            quit = 1;
        }
        if(bothnewkeys & FLAG_MOVEUP)
        {
            if(selector <= VIDEO_OPTION)
            {
                selector = BACK_OPTION;
            }
            else --selector;

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & FLAG_MOVEDOWN)
        {
            ++selector;
            if(selector > BACK_OPTION)
            {
                selector = VIDEO_OPTION;
            }

            if(SAMPLE_BEEP >= 0)
            {
                sound_play_sample(SAMPLE_BEEP, 0, savedata.effectvol, savedata.effectvol, 100);
            }
        }
        if(bothnewkeys & (FLAG_MOVELEFT | FLAG_MOVERIGHT | FLAG_ANYBUTTON))
        {

            if(SAMPLE_BEEP2 >= 0)
            {
                sound_play_sample(SAMPLE_BEEP2, 0, savedata.effectvol, savedata.effectvol, 100);
            }

            if(bothnewkeys & FLAG_ANYBUTTON)
            {
                     if(selector==BACK_OPTION) quit = 1;
                else if(selector==VIDEO_OPTION) menu_options_video();
                else if(selector==SOUND_OPTION) menu_options_sound();
                else if(selector==CONTROL_OPTION) menu_options_input();
                else if(selector==SYSTEM_OPTION)
                {
                        menu_options_system();
                        if (cheats && !forcecheatsoff)
                        {
                            y_offset = OPT_Y_POS-TOT_CHEATS;
                            if(level != NULL && _pause > 0) y_offset += CHEAT_PAUSE_POSY;
                            cheat_opt_offset = 1;
                            BACK_OPTION = END_OPTION-TOT_CHEATS+TOT_CHEATS;
                        }
                        else
                        {
                            y_offset = OPT_Y_POS;
                            cheat_opt_offset = 0;
                            BACK_OPTION = END_OPTION-TOT_CHEATS;
                        }
                }
                else if(selector==LIVES_CHEAT) livescheat = !livescheat;
                else if(selector==CREDITS_CHEAT) creditscheat = !creditscheat;
                else if(selector==HEALTH_CHEAT) healthcheat = !healthcheat;
                else quit = 1;
            }
        }
    }
    savesettings();
    if(_pause == 1)
    {
        _pause = 2;
    }
    bothnewkeys = 0;
    optionsMenu = 0;

    #undef TOT_CHEATS
    #undef OPT_Y_POS
    #undef OPT_X_POS
    #undef CHEAT_PAUSE_POSY
}

lns.initial_arguments:
if(argc > 1)
{
    argl = strlen(argv[1]);
    if(argl > 14 && !memcmp(argv[1], "offscreenkill=", 14))
    {
        DEFAULT_OFFSCREEN_KILL = getValidInt((char *)argv[1] + 14, "", "");
