    {
        printFileUsageStatistics = getValidInt((char *)argv[1] + 14, "", "");
    }

    argl = strlen(argv[argc - 1]);
    if(argl > 10 && !memcmp(argv[argc - 1], "cheatcode=", 10))
    {
      cheatcode = getValidInt((char *)argv[argc - 1] + 10, "", "");
